-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.druid.balance.Name"] = "Баланс"
L["rm.era.druid.balance.Description"] = "Баланс с 1 по 60 уровень; также ротация друида по умолчанию до выбора талантов или когда не подходит другая встроенная ротация. Звездный огонь как заполнитель, как только он изучен (до этого — Гнев; при срабатывании Благоволения природы сначала Звездный огонь), Лунный огонь и Рой насекомых поддерживаются на целях, которые проживут достаточно долго, пока у вас больше 30% маны, Гроза, когда с вами сражаются три и более врага, Волшебный огонь в группе, мгновенные заклинания в движении, ближний бой, когда мана кончилась. В облике кошки или медведя вместо этого даёт советы «Силы зверя». Напоминания: Знак дикой природы, Шипы в одиночной игре, Знамение ясности, Облик лунного совуха, когда вы не в облике, Озарение, Природный захват. Понижение ранга Звездного огня, обездвиживание и выбор цели остаются за вами."
L["rm.era.druid.balance.icyveins.Name"] = "Баланс (Icy Veins)"
L["rm.era.druid.balance.icyveins.Description"] = "Рейдовый список Icy Veins для игровых миров с лимитом в 16 отрицательных эффектов — альтернатива рекомендуемой встроенной ротации «Баланс», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Только Звездный огонь, без Лунного огня и Роя насекомых, Гроза, когда с вами сражаются три и более врага, Гнев — только пока Звездный огонь не изучен. Те же напоминания, что и в рекомендуемой встроенной ротации."
L["rm.era.druid.feral.Name"] = "Сила зверя"
L["rm.era.druid.feral.Description"] = "Кошка и медведь «Силы зверя» с 10 уровня, когда «Сила зверя» — ваша основная ветка талантов; что именно, решает ваш облик. Кошка: атака из незаметности, поддержание Волшебного огня (сила зверя), Ясность мысли тратится на Полоснуть, завершающий приём с четырёх очков серии («Разорвать», пока не изучен Свирепый укус, и в долгих боях вне рейдов; Укус при энергии ниже 63), Глубокая рана вне рейдов, Полоснуть из-за спины или Когти, когда цель бьёт вас, и смена облика ради энергии (снова Облик кошки), когда энергии сильно не хватает, а у вас Гнев 5/5 и есть лишняя мана. Медведь: Исступление при нехватке ярости, Устрашающий рев против групп и элитных противников, если не висит крик воина, Размах против двух и более врагов и при лишней ярости, иначе Волшебный огонь (сила зверя). В облике заклинателя: смена облика. Напоминания: Трепка каждым ударом, Тигриное неистовство перед боем, Ручной пробойник толпы, Озарение, Неистовое восстановление. Позиционирование остаётся за вами."
L["rm.era.druid.feral.warcrafttavern.Name"] = "Сила зверя (Warcraft Tavern, «Разорвать» и Укус)"
L["rm.era.druid.feral.warcrafttavern.Description"] = "Список Warcraft Tavern со сменой облика ради энергии — альтернатива рекомендуемой встроенной ротации «Сила зверя», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Разорвать на пяти очках серии всякий раз, когда его нет, в том числе в рейдах, затем Свирепый укус с четырёх очков серии при энергии ниже 63, Полоснуть из-за спины, смена облика, когда энергии сильно не хватает. Медведь и напоминания — как в рекомендуемой встроенной ротации."
L["rm.era.druid.feral.warcrafttavern.casual.Name"] = "Сила зверя (Warcraft Tavern, без смены облика)"
L["rm.era.druid.feral.warcrafttavern.casual.Description"] = "Список Warcraft Tavern без смены облика ради энергии — альтернатива рекомендуемой встроенной ротации «Сила зверя», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Набор пяти очков серии Полоснуть (спереди — Когти), затем Разорвать по цели, которая проживёт достаточно долго, Тигриное неистовство, Свирепый укус; иначе ждать энергию. Медведь и напоминания — как в рекомендуемой встроенной ротации."
L["rm.era.druid.feral.wowhead.Name"] = "Сила зверя (рейдовый медведь Wowhead)"
L["rm.era.druid.feral.wowhead.Description"] = "Кошка из рекомендуемой встроенной ротации «Сила зверя» вместе с рейдовым медведем в хорошем снаряжении по Wowhead: Трепка каждым ударом (Трепку по группе с переключением целей делаете сами), Размах только при запасе ярости в 60 ед., иначе Волшебный огонь (сила зверя), без Устрашающего рева и без Исступления в бою. Альтернатива рекомендуемой встроенной ротации «Сила зверя», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.era.druid.restoration.Name"] = "Исцеление"
L["rm.era.druid.restoration.Description"] = "Исцеление с 10 уровня, когда «Исцеление» — ваша основная ветка талантов. Лечит вашу текущую дружественную цель: Целительное прикосновение после Природной стремительности, Быстрое восстановление при здоровье ниже 40% на вашем собственном HoT, Омоложение и Восстановление постоянно обновляются, Восстановление как основное лечение при Улучшенном восстановлении, Целительное прикосновение высшего ранга при здоровье ниже 45% или при срабатывании Благоволения природы, иначе Целительное прикосновение 4-го ранга. С враждебной целью: Лунный огонь, Рой насекомых и Гнев. В облике кошки или медведя молчит. Напоминания: Знак дикой природы, Знамение ясности, Природная стремительность, Спокойствие, Озарение, Возрождение, снятие ядов и проклятий. Кого лечить, выбираете вы."
L["rm.era.druid.restoration.warcrafttavern.Name"] = "Исцеление (Warcraft Tavern)"
L["rm.era.druid.restoration.warcrafttavern.Description"] = "Ступени урона Warcraft Tavern — альтернатива рекомендуемой встроенной ротации «Исцеление», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. На вашей дружественной цели, без поддержания HoT, пока урон невелик: Быстрое восстановление ниже 40%, Восстановление 5-го ранга ниже 50%, Омоложение и Восстановление 3-го ранга ниже 75%, Целительное прикосновение высшего ранга при срабатывании Благоволения природы, Целительное прикосновение 3-го ранга ниже 90%. Напоминания — как в рекомендуемой встроенной ротации."
L["rm.forever.druid.balance.Name"] = "Баланс"
L["rm.forever.druid.balance.Description"] = "Баланс с 1 по 60 уровень; также используется по умолчанию для любого друида в Forever, которому не подходит другая встроенная ротация (уровни 1–9, заклинатели без талантов, «Исцеление» в одиночной игре). Начинает бой Гневом; в движении обновляет Лунный огонь, Рой насекомых и, в группе, Волшебный огонь. Гроза, когда с вами сражаются три и более врага, затем ваши собственные Лунный огонь и Рой насекомых, Звездный огонь, пока копятся заряды Затмения или действует Ясность мысли, и Гнев; когда на Гнев не хватает маны, позволяет вам сражаться в ближнем бою. В Forever здоровье и мана скрыты от аддонов, поэтому лечение себя и оценка того, стоит ли цель DoT, остаются за вами. Напоминания: Знак дикой природы, Шипы в одиночной игре, Облик лунного совуха, Омоложение перед боем в одиночной игре, Природный захват, когда противник бьёт вас, Озарение при любой готовности в бою в одиночной игре. Смена облика, контроль, Дубовая кожа и выбор цели остаются за вами. Составлено по руководствам бета-версии для 30 уровня; шаги для 31–60 уровней следуют задумке класса и не проверены."
L["rm.forever.druid.balance.tavern.Name"] = "Баланс, несколько DoT (Warcraft Tavern)"
L["rm.forever.druid.balance.tavern.Description"] = "Стиль прокачки Warcraft Tavern с несколькими DoT — альтернатива рекомендуемой встроенной ротации «Баланс», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Начинает бой Гневом, поддерживает ваши Лунный огонь и Рой насекомых на цели, обездвиживает её Гневом деревьев, когда оба эффекта висят, а с вами сражается ещё один враг, затем Гнев. Без Звездного огня (билд обходится без Затмения). Переключение на следующего врага — за вами. Напоминания: Знак дикой природы, Шипы в одиночной игре."
L["rm.forever.druid.feral.Name"] = "Сила зверя, кошка и медведь"
L["rm.forever.druid.feral.Description"] = "Кошка и медведь в одной встроенной ротации, выбор по облику; она вступает в силу, как только «Сила зверя» становится вашей основной веткой талантов (или в ней 11 очков) или когда вы принимаете облик кошки или медведя. Кошка: Накинуться или Полоснуть из Крадущегося зверя, Волшебный огонь, Разорвать на четырёх очках серии, Свирепый укус, пока действует Разорвать, Глубокая рана, затем Полоснуть, когда цель не смотрит на вас (иначе Когти). Медведь: Волшебный огонь и Звериная атака на расстоянии, Устрашающий рев в группе или против двух врагов, Неудержимый укус, Размах против трёх и более, Растерзать, Размах. В облике заклинателя предлагает Облик кошки (Облик медведя, пока у вас нет облика кошки). Напоминания: Трепка, когда хватает ярости в облике медведя, Исступление, Берсерк против больших групп или элитных противников, Озарение в одиночной игре, Знак дикой природы, Шипы. В Forever здоровье, энергия, ярость и мана скрыты от аддонов, поэтому смена облика ради энергии (powershifting), Неистовое восстановление и лечение себя остаются за вами. Провокации, прерывания и позиционирование остаются за вами."
L["rm.forever.druid.restoration.Name"] = "Исцеление"
L["rm.forever.druid.restoration.Description"] = "Групповое лечение по Warcraft Tavern, когда «Исцеление» — ваша основная ветка талантов с 11 очками. Лечит вашу текущую дружественную цель: Быстрое восстановление на цель с вашим HoT, Буйный рост, Восстановление и Омоложение, если их нет, Целительное прикосновение. В Forever здоровье и мана скрыты от аддонов, поэтому единственный признак того, кого нужно лечить, — выбранная вами цель. С враждебной целью: Лунный огонь, Рой насекомых, Гнев. Напоминания: Озарение в бою, Природная стремительность на дружественную цель в бою, Снятие проклятья и Устранение яда, Знак дикой природы; Спокойствие — за вами. Кого лечить и ранг заклинания выбираете вы; «Исцеление» в одиночной игре использует встроенную ротацию «Баланс»."
L["rm.forever.druid.restoration.icyveins.Name"] = "Исцеление, сначала HoT (Icy Veins)"
L["rm.forever.druid.restoration.icyveins.Description"] = "Лечение «сначала HoT» по Icy Veins — альтернатива рекомендуемой встроенной ротации «Исцеление», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. На дружественную цель: Омоложение, затем Восстановление, если его нет, Целительное прикосновение только при обоих активных HoT, Быстрое восстановление на цель с HoT, затем Буйный рост (в Forever здоровье скрыто, поэтому кого лечить, определяет выбранная вами цель). Озарение по готовности. В остальном — те же напоминания и действия против враждебной цели, что и во встроенной ротации «Исцеление»."
L["rm.mop.druid.balance.Name"] = "Рекомендуемая"
L["rm.mop.druid.balance.Description"] = "Рекомендуется для «Баланса» с 10 уровня; по списку 5-й фазы Wowhead и симулятор. Поддерживает Лунный огонь и Солнечный огонь и обновляет их во время соответствующего Затмения, применяет Звездопад во время Лунного затмения, Звездный поток при Падающих звездах и по готовности, Ураган во время Солнечного затмения или Астральную бурю во время Лунного против пяти врагов, Звездный огонь во время и после Лунного затмения и Гнев во время и после Солнечного. Rotation Master не может читать энергию затмения, поэтому между Затмениями продолжает применять Звездный огонь, если он был среди трёх ваших последних заклинаний, иначе Гнев. Напоминания: Знак дикой природы, Облик лунного совуха, Перевоплощение в начале Затмения и Парад планет в его конце (против элитных противников или в долгих боях), Природная чуткость, Сила Природы, Природная стремительность ради Сна Кенария, Озарение, Столп солнечного света, Дубовая кожа и Обновление при низком здоровье. Расстановка Диких грибов остаётся ручной; напоминание о взрыве по умолчанию выключено. Молчит, пока вы применяете заклинание, путешествуете, находитесь в облике кошки или медведя или у вас нет враждебной цели."
L["rm.mop.druid.feral.Name"] = "Рекомендуемая"
L["rm.mop.druid.feral.Description"] = "Рекомендуется для «Силы зверя» с 10 уровня; по симулятор и списку 5-й фазы Wowhead. Переводит вас в Облик кошки, начинает бой из Крадущегося зверя Диким ревом и Накинуться, поддерживает Дикий рев, использует Стремительность хищника для Целительного прикосновения на четырёх или пяти очках серии при Сне Кенария, «Разорвать» на пяти очках (при здоровье цели ниже 25% его обновляет Свирепый укус), Свирепый укус на пяти очках, пока у «Разорвать» и Дикого рева остаётся по шесть секунд, Глубокая рана, Взбучка при Ясности мысли, Полоснуть при Ясности мысли или Берсерке, когда цель не атакует вас (Rotation Master не может определить, стоите ли вы за ней), и Увечье; Взбучка и Размах против четырёх врагов. В облике медведя даёт короткий список танкования. Напоминания: Тигриное неистовство при энергии ниже 35, Берсерк вместе с ним против элитных противников или в долгих боях, Перевоплощение, Сила Природы, Природная чуткость, Лобовая атака, Инстинкты выживания и Дубовая кожа при низком здоровье, Знак дикой природы. Вплетение облика медведя и Гнева, а также Сердце дикой природы остаются ручными."
L["rm.mop.druid.feral.icyveins.Name"] = "Укус только при добивании (Icy Veins)"
L["rm.mop.druid.feral.icyveins.Description"] = "Порядок «Силы зверя» по Icy Veins (правило Wowhead об Укусе с ним согласно) — альтернатива рекомендуемой встроенной ротации «Сила зверя»: включите её и выключите ту или повысьте её приоритет. То же начало боя, Дикий рев, Целительное прикосновение и AoE, но при здоровье цели выше 25% очки серии идут только на «Разорвать» и Дикий рев: Свирепый укус лишь обновляет «Разорвать» при добивании (или тратит пять очков, пока вы не изучили «Разорвать»). Глубокая рана обновляется за две секунды, Взбучка — только при Ясности мысли, а Берсерк ждёт 90 энергии, когда до Тигриного неистовства не меньше 15 секунд."
L["rm.mop.druid.guardian.Name"] = "Рекомендуемая"
L["rm.mop.druid.guardian.Description"] = "Рекомендуется для танков «Стража» с 10 уровня; по симулятор и списку 5-й фазы Wowhead. Переводит вас в Облик медведя, начинает бой Волшебным огнем с дистанции или Увечьем, поддерживает Слабые удары Взбучкой и Ослабленную броню Волшебным огнем против элитных противников, использует Целительное прикосновение при Сне Кенария, когда вы ранены, Увечье по готовности, Взбучка и Размах против трёх врагов, затем Растерзать, Взбучка и Волшебный огонь. В облике кошки (Сердце дикой природы) даёт короткий список урона. Напоминания: Дикая защита всякий раз, когда её нет, Исступление ради ярости, Неистовое восстановление при низком здоровье или у предела ярости, Трепка при ярости выше 90 или при Зубах и когтях, Дубовая кожа, пока цель атакует вас, Инстинкты выживания при низком здоровье, Берсерк и Перевоплощение против двух врагов или босса, Сила Природы, Природная чуткость, Щит Кенария, Лобовая атака, Знак дикой природы. Провокации и Мощь Урсока остаются ручными (оба напоминания по умолчанию выключены)."
L["rm.mop.druid.restoration.Name"] = "Рекомендуемая"
L["rm.mop.druid.restoration.Description"] = "Рекомендуется для «Исцеления» с 10 уровня; по групповому лечению 5-й фазы Wowhead. Лечит вашу текущую дружественную цель или вас, если цели нет; кого лечить, решаете вы. Быстрое восстановление на цель с вашим HoT, когда у неё мало здоровья, когда спала Гармония или перед Буйным ростом при Душе леса; Буйный рост, когда ранены трое рядом; мгновенное Целительное прикосновение при Природной стремительности; Восстановление при Ясности мысли или по умирающей цели; Омоложение; затем Целительное прикосновение и Покровительство Природы, пока вы стоите на месте. Атакуемая цель получает Лунный огонь и Гнев. Напоминания: наложения Жизнецвета и Железная кора на ваш фокус (сделайте танка фокусом), Дикий гриб: лечение при уроне по группе, Сила Природы, Перевоплощение, Природная чуткость, Природная стремительность, Озарение, Природный целитель, Щит Кенария, Дубовая кожа, Знак дикой природы. Напоминания о расстановке Диких грибов, Спокойствии и Сотворении по умолчанию выключены."
L["rm.mop.druid.restoration.wowhead.Name"] = "Лечение танка (Wowhead)"
L["rm.mop.druid.restoration.wowhead.Description"] = "Порядок лечения одного танка по Wowhead — альтернатива рекомендуемой встроенной ротации «Исцеление» на случай, когда вас назначили на танка: включите её и выключите ту или повысьте её приоритет. Держите танка в цели: ротация поддерживает на нём три Жизнецвета и Омоложение, использует Восстановление при сильном уроне, Покровительство Природы при слабом, Целительное прикосновение, когда Жизнецвет и Омоложение уже действуют, а у танка меньше половины здоровья, и Быстрое восстановление, чтобы держать его здоровье полным. Те же напоминания, что и в рекомендуемой встроенной ротации."
L["rm.mop.druid.unspecialized.Name"] = "До выбора специализации"
L["rm.mop.druid.unspecialized.Description"] = "Для уровней 1–9 или любого друида, который ещё не выбрал специализацию; как только вы её выберете, в силу вступают встроенные ротации специализаций. В облике кошки поддерживает Глубокую рану, тратит пять очков серии (или два по умирающей цели) на Свирепый укус и набирает их Увечьем; в облике медведя использует Увечье и Трепку. Иначе начинает бой Гневом, поддерживает Лунный огонь на целях, которые проживут достаточно долго, применяет Гнев (в движении — Лунный огонь) и предлагает Омоложение на себя, когда у вас меньше половины здоровья и вы одни. Молчит, пока вы применяете заклинание, путешествуете или у вас нет враждебной цели."
L["rm.retail.druid.balance.Name"] = "Боевой помощник Blizzard"
L["rm.retail.druid.balance.Description"] = "Рекомендуется для специализации «Баланс». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что Боевой помощник оставляет вам: Парад планет (или Воплощение) в бою, Столп солнечного света против прерываемого заклинания, Облик лунного совуха и Знак дикой природы между боями, а также Дубовая кожа и ваша расовая способность по готовности в бою. В бою заклинания противников скрыты, поэтому Столп солнечного света загорается только там, где игра его показывает; на Retail здоровье скрыто, поэтому момент для Дубовой кожи — на ваше усмотрение."
L["rm.retail.druid.balance.guide.Name"] = "Для справки (Icy Veins, SimulationCraft и Wowhead)"
L["rm.retail.druid.balance.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Баланса» по руководствам. Ваши DoT, Затмение и срабатывания скрыты от аддонов в бою в Midnight, поэтому ротация не может там работать; читайте её или продублируйте, чтобы поэкспериментировать. Астральная мощь на Retail скрыта, поэтому Звездный поток тратится по стоимости, а не до достижения максимума. Начало боя: Облик лунного совуха и Гнев. Солнечный огонь и Лунный огонь, если их нет или они вот-вот спадут; Затмение, когда ни одно не активно (Лунное против трёх и более врагов, иначе Солнечное); Звездопад при Искажении Ткача Звезд, Прикосновении к космосу или против групп врагов; Звездный поток при Дымке Ткача Звезд или Прикосновении к космосу; Новолуние, Полумесяц и Полная луна; Дикий гриб во время Затмения; Звездный поток, когда хватает ресурса; Звездный огонь во время Лунного затмения или против групп врагов, иначе Гнев. Напоминания: Парад планет или Воплощение, Ярость Элуны и Сила природы перед Затмением, Созыв духов во время Парада планет, Столп солнечного света, а также вспомогательные напоминания."
L["rm.retail.druid.feral.Name"] = "Боевой помощник Blizzard"
L["rm.retail.druid.feral.Description"] = "Рекомендуется для специализации «Сила зверя». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что Боевой помощник оставляет вам: Берсерк (или Воплощение) в бою, Лобовая атака против прерываемого заклинания, Инстинкты выживания, Дубовая кожа и ваша расовая способность по готовности в бою, а также Облик кошки и Знак дикой природы между боями. В бою заклинания противников скрыты, поэтому прерывание загорается только там, где игра его показывает; на Retail здоровье скрыто, поэтому момент для защитных способностей — на ваше усмотрение."
L["rm.retail.druid.feral.guide.Name"] = "Для справки (Icy Veins и SimulationCraft)"
L["rm.retail.druid.feral.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Силы зверя» по руководствам. Кровотечения и срабатывания скрыты в бою в Midnight (очки серии — нет), поэтому ротация не может там работать; энергия на Retail скрыта. Начало боя: Облик кошки, Крадущийся зверь и Глубокая рана. Быстрый укус; Свирепый укус при Жажде сверххищника; на пяти очках серии — Первобытный гнев против двух и более врагов, Разорвать, если его нет или идут его последние секунды, иначе Свирепый укус, причём ротация ждёт энергию, а не набирает очки сверх пяти; меньше пяти очков — Глубокая рана, если её нет или она вот-вот спадёт, Лунный огонь с Лунным вдохновением, Размах против трёх и более врагов, Полоснуть. Напоминания: Тигриное неистовство по готовности в бою, Берсерк или Воплощение и Дикое или Бурное бешенство (при двух очках или меньше) под Тигриным неистовством, Созыв духов под Тигриным неистовством и Берсерком при действующем Разорвать, Лобовая атака, Инстинкты выживания, а также вспомогательные напоминания. Учёт снапшотов (силы кровотечений в момент наложения) остаётся за вами."
L["rm.retail.druid.guardian.Name"] = "Боевой помощник Blizzard"
L["rm.retail.druid.guardian.Description"] = "Рекомендуется для специализации «Страж». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; Боевой помощник играет только на урон. Рядом с ним — напоминания о том, что он оставляет вам: Берсерк (или Воплощение) и Созыв духов в бою, Железный мех, Неистовое восстановление, Инстинкты выживания, Дубовая кожа и ваша расовая способность по готовности в бою, Лобовая атака против прерываемого заклинания, а также Облик медведя и Знак дикой природы между боями. В бою заклинания противников скрыты, поэтому Лобовая атака загорается только там, где игра их показывает; здоровье и ярость на Retail скрыты, поэтому момент для защитных способностей — на ваше усмотрение, а Железный мех не может ждать порога ярости."
L["rm.retail.druid.guardian.guide.Name"] = "Для справки (Icy Veins и Wowhead)"
L["rm.retail.druid.guardian.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Стража» по руководствам. Отрицательные эффекты и срабатывания скрыты в бою в Midnight, поэтому ротация не может там работать; ярость и здоровье на Retail скрыты, поэтому сброс ярости на Смести и Трепку при 80 ед. остаётся за вами. Взбучка и Увечье по готовности, Красная луна против одной цели, Лунный огонь, если его нет, или при Галактическом страже, Размах. Напоминания по готовности в бою: Железный мех, Неистовое восстановление, Инстинкты выживания; Облик медведя между боями; Берсерк или Воплощение, Лунный луч, Созыв духов, Сердце дикой природы, Лобовая атака, а также вспомогательные напоминания."
L["rm.retail.druid.guardian.simc.Name"] = "Упор на защиту, для справки (SimulationCraft)"
L["rm.retail.druid.guardian.simc.Description"] = "Только для справки, по умолчанию выключена: список SimulationCraft для «Стража», который в первую очередь тратит ярость на Железный мех. Скрытые боевые данные не дают этой ротации работать в бою в Midnight, а ярость на Retail скрыта, поэтому пороги ярости опущены. Железный мех под Берсерком; Взбучка, если её нет, она вот-вот спадёт или у неё меньше трёх наложений; Трепка при Окровавленном мехе; Взбучка против трёх и более врагов; Увечье, пока действует Красная луна; Красная луна; Увечье; Взбучка; Лунный огонь; Размах. Вплетание облика кошки из этого списка опущено. Напоминания: Облик медведя, Неистовое восстановление, Инстинкты выживания, Берсерк или Воплощение, Лунный луч, Созыв духов, Лобовая атака, а также вспомогательные напоминания."
L["rm.retail.druid.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.druid.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию друида). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций друида, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.retail.druid.restoration.Name"] = "Боевой помощник Blizzard с поддержанием"
L["rm.retail.druid.restoration.Description"] = "Рекомендуется для специализации «Исцеление». Если в цели враг, подсвечивает предложение Боевого помощника Blizzard — список урона Blizzard для «Исцеления» в облике кошки или заклинателя. Иначе предлагает поддерживающие заклинания по Icy Veins для вашей дружественной цели (или для вас): Жизнецвет, Период цветения в бою, Быстрое восстановление по цели с Омоложением, Буйный рост в группе в бою, Восстановление при Ясности мысли или пяти наложениях Изобилия, Омоложение, если его нет. Здоровье и мана на Retail скрыты, поэтому эти заклинания следуют выбранной вами цели, а не тому, насколько кто-то ранен; ваши эффекты исцеления со временем скрыты в бою в Midnight, поэтому шаги, которые их читают, там ждут. Кого лечить и все лечащие способности с восстановлением — решать вам. Напоминания: Озарение, Дубовая кожа и ваша расовая способность по готовности в бою, Знак дикой природы между боями."
L["rm.sod.druid.balance.Name"] = "Баланс (SoD)"
L["rm.sod.druid.balance.Description"] = "Баланс для сезона открытий с 1 по 60 уровень; также ротация по умолчанию для любого друида, которому не подходит другая встроенная ротация сезона открытий. Звездный поток всякий раз, когда его эффекта нет, Солнечный огонь и Лунный огонь на целях, которые проживут достаточно долго, Звездный огонь — только когда его усиливает Звездный поток или Лунное затмение, Гнев как заполнитель, Гроза против шести и более врагов (четырёх — с выгравированными Штормовыми ветрами), Рой насекомых — только в движении. Руны используются по мере того, как вы их гравируете. В облике кошки или медведя даёт советы «Силы зверя». Напоминания: Облик лунного совуха, Звездопад, мгновенное Целительное прикосновение на умирающего союзника, снятие проклятий и ядов, Буйный рост на раненую группу, Озарение. Распространение DoT на другие цели остаётся за вами."
L["rm.sod.druid.balance.icyveins.Name"] = "Баланс (SoD, Icy Veins)"
L["rm.sod.druid.balance.icyveins.Description"] = "Список Icy Veins для сезона открытий — альтернатива рекомендуемой встроенной ротации «Баланс» для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Звездный поток по готовности, Гроза против четырёх и более врагов (ради Штормовых ветров), Звездный огонь, когда его усиливает Звездный поток, Лунный огонь, Солнечный огонь и Рой насекомых постоянно поддерживаются, Гнев как заполнитель. Напоминания — как в рекомендуемой встроенной ротации."
L["rm.sod.druid.balance.wowhead.Name"] = "Баланс (SoD, Wowhead)"
L["rm.sod.druid.balance.wowhead.Description"] = "Список Wowhead для 8-й фазы — альтернатива рекомендуемой встроенной ротации «Баланс» для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Начало боя Гневом, Звездный поток по готовности, Гроза против шести и более врагов, Рой насекомых — только в движении, Солнечный огонь и Лунный огонь постоянно поддерживаются, Гнев, пока вашему Солнечному огню осталось меньше 5 секунд, когда выгравированы Огни Элуны, чтобы продлить его, Звездный огонь при Лунном затмении, иначе Гнев. Напоминания — как в рекомендуемой встроенной ротации."
L["rm.sod.druid.feral.Name"] = "Сила зверя, кошка (SoD)"
L["rm.sod.druid.feral.Description"] = "Кошка для сезона открытий; выбирается, когда выгравирован Дикий рев (или когда «Сила зверя» — ваша основная ветка без другой руны для ног). Волшебный огонь (сила зверя), если его нет, Дикий рев, Размах (кошка) против четырёх и более врагов, отрицательный эффект Увечья, Ясность мысли на Полоснуть, «Разорвать» на пяти очках серии, пока Дикому реву осталось 8 секунд, Глубокая рана, Полоснуть из-за спины или Увечье спереди, смена облика ради энергии при Гневе 5/5, в последнюю очередь обновление Волшебного огня. В облике медведя даёт советы для танка. Напоминания: Тигриное неистовство при 60 энергии или меньше, Берсерк вместе с Тигриным неистовством, Трепка, Озарение. Позиционирование остаётся за вами."
L["rm.sod.druid.restoration.Name"] = "Исцеление (SoD)"
L["rm.sod.druid.restoration.Description"] = "Исцеление для сезона открытий; выбирается, когда выгравирован Жизнецвет (или когда «Исцеление» — ваша основная ветка без другой руны для ног). Лечит вашу текущую дружественную цель: мгновенное Целительное прикосновение после Природной стремительности или Гнева Ярости Бури, Буйный рост, когда ранены двое и более союзников рядом, Быстрое восстановление на вашем HoT ради Периода цветения или при здоровье ниже 40%, три наложения Жизнецвета обновляются за секунду до конца, Омоложение, Восстановление ниже 60%, Покровительство природы, Целительное прикосновение 4-го ранга. С враждебной целью: Солнечный огонь, Лунный огонь, Гнев. Напоминания: Древо жизни и Инстинкты выживания в тяжёлые моменты, Природная стремительность, Спокойствие, Озарение, Возрождение, Оживление, рассеивание. Кого лечить, выбираете вы."
L["rm.sod.druid.tank.Name"] = "Медведь-танк (SoD)"
L["rm.sod.druid.tank.Description"] = "Медведь-танк для сезона открытий; выбирается, когда выгравирован Растерзать. Волшебный огонь (сила зверя) или Солнечный огонь (медведь), чтобы начать бой с дистанции, Растерзать до того, как он спадёт, Увечье по готовности, Растерзать, Размах; против трёх и более врагов — Увечье под Берсерком и Размах. В облике кошки играет список кошки для второго танка; в облике заклинателя переходит в облик медведя. Напоминания: Трепка при 30 ярости, Берсерк, Инстинкты выживания, Неистовое восстановление и Дубовая кожа при низком здоровье, Исступление между боями, Устрашающий рев против элитных противников. Провокации и выбор цели остаются за вами."
L["rm.sod.druid.tank.simulator.Name"] = "Медведь-танк (SoD, кошачье чередование симулятор)"
L["rm.sod.druid.tank.simulator.Description"] = "По умолчанию выключена; для опытных игроков, чьё снаряжение также даёт Дикий рев. Чередование с кошкой из 7-й фазы по симулятор: выйти из облика медведя в облик кошки, когда ваша Глубокая рана спала, поддерживать Дикий рев и Глубокую рану (Тигриное неистовство, Увечье для набора очков), затем вернуться в Облик лютого медведя и играть список танка. Напоминания — как в рекомендуемой встроенной ротации танка."
L["rm.tbc.druid.balance.Name"] = "Баланс"
L["rm.tbc.druid.balance.Description"] = "Заклинатель ветки «Баланс» с 1 по 70 уровень; также используется по умолчанию для любого друида, которому не подходит другая встроенная ротация. Начинает бой Звездным огнем (до 20 уровня — Гневом), Рой насекомых и Лунный огонь в движении, Волшебный огонь в группе, Гроза при трёх и более врагах, Лунный огонь, когда он истёк и у вас есть 30% маны, Звездный огонь при Благоволении природы, Гнев по цели в ближнем бою, затем Звездный огонь (Гнев, пока он не изучен). В облике кошки, медведя и походном облике советов нет. Напоминания: Знак дикой природы, Шипы в одиночной игре, Знамение ясности, Облик лунного совуха, Сила Природы в долгом бою, Озарение при нехватке маны."
L["rm.tbc.druid.feral.icyveins.Name"] = "Сила зверя (Icy Veins, Warcraft Tavern и симулятор)"
L["rm.tbc.druid.feral.icyveins.Description"] = "Кошка и медведь для ветки «Сила зверя» в зависимости от вашего облика. Кошка: атака из незаметности (Наскок, Накинуться или Полоснуть), Волшебный огонь (сила зверя), «Разорвать» на четырёх очках серии по цели, которая проживёт достаточно долго, Свирепый укус между «Разорвать» без Ясности мысли, поддержание Увечья, Полоснуть из-за спины или Увечье/Когти, когда цель бьёт вас. Медведь: Волшебный огонь, Растерзать обновляется до того, как спадёт, Устрашающий рев, если не висит крик воина, Размах против групп, Увечье, пять наложений Растерзать, Размах. В облике заклинателя предлагает Облик кошки (или медведя). Напоминания: Знак, Шипы, Знамение, Трепка при лишней ярости, Тигриное неистовство перед боем, Неистовое восстановление. Смена облика ради энергии (powershifting) — необязательный шаг, по умолчанию выключенный (нужен макрос для powershift)."
L["rm.tbc.druid.feral.wowhead.Name"] = "Сила зверя (Wowhead)"
L["rm.tbc.druid.feral.wowhead.Description"] = "«Сила зверя» по Wowhead — альтернатива рекомендуемой встроенной ротации «Сила зверя» от Icy Veins, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Разорвать всякий раз, когда он спал, на четырёх очках серии, а Свирепый укус — только по цели, которая вот-вот умрёт (без вплетения укусов); медведь тратит свободные ГКД на Растерзать перед Размахом. Озарение, когда у кошки кончается мана. В остальном — как вариант Icy Veins."
L["rm.tbc.druid.restoration.Name"] = "Исцеление"
L["rm.tbc.druid.restoration.Description"] = "Лечение для ветки «Исцеление» на дружественной цели (или на себе): Целительное прикосновение после Природной стремительности, Быстрое восстановление на умирающую цель с вашим Омоложением или Восстановлением, три постоянно обновляемых наложения Жизнецвета в бою, Омоложение и Восстановление, если их нет, затем Восстановление в облике Древа жизни или Целительное прикосновение вне его. Против враждебной цели — Лунный огонь и Гнев для одиночной игры. Напоминания: Знак, Знамение, Древо жизни, Природная стремительность, Спокойствие, Озарение и Возрождение. Кого лечить и понижение ранга заклинаний остаются за вами."
